INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 2: Bảng tuần hoàn', 1, 'Nhóm nguyên tố nào sau đây trong bảng tuần hoàn không chứa kim loại:', 'VIIIB', 'VIIIA', 'VA', 'IVB', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 2: Bảng tuần hoàn', 1, 'Ion M2+ có tổng số hạt proton, electron, nơtron, là 80. Số hạt mang điện nhiều hơn số hạt không mang điện là 20. Trong bảng tuần hoàn  M thuộc .', 'Chu kì 4, nhóm IIA.', 'Chu kì 3 nhóm VIIIB.', 'Chu kì 4, nhóm VIIIB B.', 'Chu kì 4, nhóm VIIIA.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 2: Bảng tuần hoàn', 1, 'Ma túy dù ở dạng nào khi đưa vào cơ thể con người đều có thể làm thay đổi chức năng sinh lí. Ma túy có tác dụng ức chế kích thích mạnh mẽ gây ảo giác làm cho người dùng không làm chủ được bản thân. Nghiện ma túy sẽ dẫn tới rối loạn tâm, sinh lý, rối loạn tiêu hóa, rối loạn chức năng thần kinh, rối loạn tuần hoàn, hô hấp. Tiêm chích ma túy có thể gây trụy tim mạch dễ dẫn đến tử vong, vì vậy phải luôn nói không với ma túy. Nhóm chất nào sau đây là ma túy (cấm dùng)?', 'Penixilin, ampixilin, erythromixin.', 'Thuốc phiện, cần sa, heroin, cocain.', 'Thuốc phiện, penixilin, moocphin.', 'Seduxen, cần sa, ampixilin, cocain.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 2: Bảng tuần hoàn', 1, 'Phát biểu nào sau đây là sai?', 'Nguyên tử kim loại thường có 1, 2 hoặc 3 electron ở lớp ngoài cùng.', 'Các nhóm A bao gồm các nguyên tố s và nguyên tố p.', 'Trong một chu kì, bán kính nguyên tử kim loại nhỏ hơn bán kính nguyên tử phi kim.', 'Các kim loại thường có ánh kim do các electron tự do phản xạ ánh sáng nhìn thấy được.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 2: Bảng tuần hoàn', 1, 'Theo chiều tăng dần của điện tích hạt nhân các kim loại kiềm có:
(I). Bán kính nguyên tử tăng dần.
(II). Năng lượng ion hóa giảm dần.
(III). Độ âm điện tăng dần.
(IV). Tính khử tăng dần.
(V). Khối lượng riêng giảm dần.
(VI). Độ cứng giảm dần.
(VII). Nhiệt độ nóng chảy giảm dần.
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 2: Bảng tuần hoàn', 1, 'Cấu hình electron của một ion X3+ là 1s22s22p63s23p63d5. Trong bảng tuần hoàn các nguyên tố hoá học, nguyên tố X thuộc:', 'Chu kỳ 4, nhóm VIII A', 'Chu kỳ 4, nhóm VIII B', 'Chu kỳ 4, nhóm II B', 'Chu kỳ 3, nhóm VIII B', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Theo quy tắc octet, khi hình thành liên kết hóa học, các nguyên tử có xu hướng nhường, nhận hoặc góp chung electron để đạt tới cấu hình electron bền vững của', 'kim loại kiềm.', 'kim loại chuyển tiếp.', 'khí hiếm.', 'phi kim (halogen).', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Liên kết ion là liên kết được hình thành bởi', 'lực hút tĩnh điện giữa các ion mang điện tích trái dấu.', 'sự góp chung các cặp electron hóa trị.', 'sự cho - nhận cặp electron hóa trị.', 'lực hút giữa các phân tử phân cực.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Phân tử nào sau đây có liên kết cộng hóa trị không phân cực?', 'HCl.', 'H2O.', 'N2.', 'NH3.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Trong phân tử NaCl, liên kết giữa Na và Cl là liên kết', 'cộng hóa trị phân cực.', 'ion.', 'cộng hóa trị không phân cực.', 'cho - nhận.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Liên kết hydrogen là', 'liên kết hình thành do sự góp chung electron giữa nguyên tử H và nguyên tử phi kim.', 'lực hút tĩnh điện yếu giữa phần tử mang điện tích dương của nguyên tử H và phần tử mang điện tích âm của nguyên tử khác (F, O, N).', 'tương tác yếu giữa các phân tử không phân cực.', 'liên kết hóa học bền vững nhất trong phân tử.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Tương tác Van der Waals có tác dụng', 'làm tăng nhiệt độ sôi và nhiệt độ nóng chảy của các chất.', 'làm giảm nhiệt độ sôi và nhiệt độ nóng chảy của các chất.', 'làm tăng độ bền của liên kết hóa học bên trong phân tử.', 'làm thay đổi tính chất hóa học của các chất.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Hợp chất nào sau đây có liên kết cộng hóa trị phân cực?', 'Cl2.', 'O2.', 'CH4.', 'H2O.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Nguyên tử Na (Z=11) có cấu hình electron 1s² 2s² 2p⁶ 3s¹. Để đạt cấu hình của khí hiếm gần nhất, Na có xu hướng:', 'nhường 1 electron.', 'nhận 1 electron.', 'nhường 2 electron.', 'nhận 7 electron.', 'A');
