INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 3: Liên kết hóa học', 1, 'Chất nào sau đây tồn tại ở thể lỏng trong điều kiện thường chủ yếu do có liên kết hydrogen liên phân tử?', 'H2S.', 'CH4.', 'H2O.', 'CO2.', 'C');
