INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 4: Phản ứng oxi hóa – khử', 1, 'Trong phản ứng: 2NaOH + 2Al + 2H2O   2NaAlO2 + 3H2. Al đóng vai trò là', 'chất  oxi hóa', 'chất lưỡng tính', 'chất khử.', 'chất bị khử', 'C');
