INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 1, 'Chương 4: Phản ứng oxi hóa – khử', 1, 'Chất khử được dùng trong quá trình sản xuất gang là', 'cacbon monooxit.', 'hiđro.', 'nhôm.', 'than cốc.', 'D');
