INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Phản ứng tỏa nhiệt là phản ứng hóa học trong đó', 'có sự hấp thụ nhiệt năng từ môi trường.', 'có sự giải phóng nhiệt năng ra môi trường.', 'năng lượng của hệ phản ứng không thay đổi.', 'nhiệt độ của môi trường xung quanh giảm xuống.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Điều kiện chuẩn để xác định biến thiên enthalpy chuẩn của phản ứng (ΔrH°298) là', 'áp suất 1 atm và nhiệt độ 298 K.', 'áp suất 1 bar và nhiệt độ 298 K (25 °C).', 'áp suất 1 bar và nhiệt độ 273 K (0 °C).', 'áp suất 1 atm và nhiệt độ 273 K.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Nhiệt tạo thành chuẩn (ΔfH°298) của các đơn chất ở trạng thái bền vững nhất bằng', '< 0.', '> 0.', '0.', '1.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Đối với phản ứng thu nhiệt, dấu của biến thiên enthalpy chuẩn (ΔrH°298) có giá trị', 'dương (> 0).', 'âm (< 0).', 'bằng không (= 0).', 'có thể âm hoặc dương.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Phản ứng nào sau đây trong thực tế thường là phản ứng tỏa nhiệt?', 'Phản ứng nhiệt phân CaCO3 (đá vôi).', 'Phản ứng đốt cháy khí than (CH4) trong oxi.', 'Phản ứng phân hủy KMnO4.', 'Phản ứng hòa tan muối NH4Cl vào nước.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Công thức tính biến thiên enthalpy chuẩn của phản ứng (ΔrH°298) theo nhiệt tạo thành chuẩn (ΔfH°298) là', 'ΔrH°298 = Tổng ΔfH°298 (sản phẩm) - Tổng ΔfH°298 (chất đầu)', 'ΔrH°298 = Tổng ΔfH°298 (chất đầu) - Tổng ΔfH°298 (sản phẩm)', 'ΔrH°298 = Tổng ΔfH°298 (sản phẩm) + Tổng ΔfH°298 (chất đầu)', 'ΔrH°298 = Tổng ΔfH°298 (chất đầu) / Tổng ΔfH°298 (sản phẩm)', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Công thức tính biến thiên enthalpy chuẩn của phản ứng theo năng lượng liên kết (Eb) áp dụng cho chất khí là', 'ΔrH°298 = Tổng Eb (sản phẩm) - Tổng Eb (chất đầu)', 'ΔrH°298 = Tổng Eb (chất đầu) - Tổng Eb (sản phẩm)', 'ΔrH°298 = Tổng Eb (chất đầu) + Tổng Eb (sản phẩm)', 'ΔrH°298 = Tổng Eb (sản phẩm) / Tổng Eb (chất đầu)', 'B');
