INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (10, 2, 'Chương 5: Năng lượng hóa học', 1, 'Năng lượng liên kết (Eb) là', 'năng lượng tỏa ra khi hình thành 1 mol liên kết từ các nguyên tử ở thể khí.', 'năng lượng cần cung cấp để phá vỡ 1 mol liên kết đó ở thể khí thành các nguyên tử ở thể khí.', 'năng lượng tối thiểu để phân tử tham gia phản ứng.', 'năng lượng nhiệt sinh ra khi đốt cháy 1 mol chất.', 'B');
