INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Phát biểu nào sau đây là đúng?', 'Trong công nghiệp nhôm được sản xuất từ quặng đolomit.', 'Tất cả các phản ứng của lưu huỳnh với kim loại đều cần đun nóng', 'Ca(OH)2 được dùng làm mất tính cứng vĩnh cửu của nước.', 'CrO3 tác dụng với nước tạo ra hỗn hợp axit', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Cho một số nhận định về nguyên nhân gây ô nhiễm môi trường không khí như sau:
