INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Cho dãy các chất sau: anilin, phenyl fomat, fructozơ, glyxylvalin (Gly-val), glixerol, triolein. Số chất bị thủy phân trong môi trường axit là', '4', '3', '5', '6', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chọn phát biểu đúng:', 'Trong môi trường axit, ion Cr3+ có tính khử mạnh', 'Trong môi trường kiềm, ion Cr3+ có tính oxi hóa mạnh', 'Trong dung dịch ion Cr3+  có tính lưỡng tính', 'Trong dung dịch ion Cr3+ vừa có tính oxi hóa vừa có tính khử', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Axit fomic có trong nọc kiến. Khi bị kiến cắn, nên chọn chất nào sau đây bôi vào vết thương để giảm sưng tấy?', 'Nước.', 'Giấm ăn.', 'Muối ăn.', 'Vôi tôi.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Công thức phân tử tổng quát của este tạo bởi ancol no, đơn chức, mạch hở và axit cacboxylic không no, có một liên kết đôi C=C, đơn chức, mạch hở là', 'CnH2n-2O2.', 'CnH2n+1O2.', 'CnH2n+2O2.', 'CnH2nO2.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Axit cacboxylic nào dưới đây có mạch cacbon phân nhánh, làm mất màu dung dịch brom?', 'axit propanoic', 'axit metacrylic', 'Axit 2 – metylpropanoic', 'Axit acrylic.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Axit nào sau đây là axit béo?', 'Axit axetic', 'Axit glutamic', 'Axit stearic', 'Axit ađipic', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, '“Hiệu ứng nhà kính” gây ra do sự tăng nồng độ CO2, làm cho nhiệt độ của trái đất nóng lên. Mặt trái của “hiệu ứng nhà kính” là gây ra sự khác thường về khí hậu, gây hạn hán, lũ lụt, ảnh hưởng đến môi trường sinh thái và cuộc sống của con người. Trong các biện pháp sau:
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Số đồng phân của α- amino axit C5H11NO2 có mạch cacbon phân nhánh là', '3', '4', '1', '2', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Nhận xét nào đúng trong các nhận xét sau?', 'Thủy phân este trong môi trường bazơ là phản ứng thuận nghịch.', 'Este có nhiệt độ sôi thấp hơn so với axit và ancol có cùng số nguyên tử cacbon hoặc khối lượng mol phân tử tương đương.', 'Khi thay thế nguyên tử H trong phân tử axit RCOOH bằng gốc R’ ta được este có dạng
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Phát biểu không đúng là', 'Etylamin tác dụng với axit nitrơ ở nhiệt độ thường tạo ra etanol.', 'Protein là những polipeptit cao phân tử có phân tử khối từ vài chục nghìn đến vài triệu.', 'Metylamin tan trong nước cho dung dịch có môi trường bazơ.', 'Đipeptit glyxylalanin (mạch hở) có 2 liên kết peptit.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chất nào sau đây có thể oxi hoá Zn thành Zn2+?', 'Fe', 'Mg2+.', 'Al3+.', 'Ag+.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Hợp chất CH3 - CH(NH2) - COOH có tên là( sai đề: tên không đúng là)', 'Axit α - amino propanoic', 'Alanin.', 'Axit 2 - amino propionic.', 'Axit β - amino propanoic.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Axit glutamic là chất có tính', 'trung tính.', 'axit', 'lưỡng tính.', 'Bazơ', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chất nào sau đây tham gia phản ứng  cộng H2:', 'axit stearic', 'tripanmitin', 'triolein', 'tristearin', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Để biến các chất béo chứa axit không no thành chất béo chứa gốc axit no, người ta thực hiện quá trình', 'làm lạnh.', 'đông lạnh.', 'hiđro hóa.', 'cô cạn ở nhiệt độ cao .', 'C');
