INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Nhận xét nào sau đây không đúng?', 'BaSO4 và BaCrO4 hầu như không tan trong nước.', 'SO3 và CrO3 đều là oxit axit.', 'Al2O3 và CrO đều là oxit lưỡng tính.', 'Fe(OH)2 và Cr(OH)2 đều là bazơ và có tính khử.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chọn phát biểu sai', 'Cho axit glutamic tác dụng với NaOH dư thì tạo sản phẩm là bột ngọt, mì chính.', 'Các aminoaxit đều là chất rắn ở nhiệt độ thường.', 'Axit glutamit làm quỳ tím hóa đỏ.', 'Lysin làm quỳ tím hóa xanh.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Lớp ozon ở tầng bình lưu của khí quyển là tấm lá chắn tia tử ngoại của Mặt trời, bảo vệ sự sống trên Trái đất. Hiện tượng suy giảm tầng ozon đang là một vấn đề môi trường toàn cầu. Nguyên nhân của hiện tượng này là do', 'Chất thải CFC do con người gây ra', 'Chất thải CO2', 'Sự thay đổi của khí hậu', 'Các hợp chất hữu cơ', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Cho glixerol (glixerin) phản ứng với hỗn hợp axit béo gồm C17H35COOH và C15H31COOH, số loại trieste được tạo ra tối đa là', '5.', '3.', '4.', '6.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Dãy các dung dịch và chất lỏng đều làm đổi màu quì tím tẩm nước cất là', 'Phenol, anilin, natri axetat, axit glutamic, axit axetic.', 'Etylamin, natri phenolat, axit aminoaxetic, axit fomic, axit axetic.', 'Etylamin, natri phenolat, phenylamoni clorua, axit glutamic, axit axetic.', 'Anilin, natri phenolat, axit fomic, axit glutamic, axit axetic.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Khi cho CrO3 tác dụng với nuớc thì', 'Thu đuợc axit H2CrO4 và H2Cr2O7', 'Chỉ thu đuợc axit H2Cr2O7', 'Chỉ thu đuợc axit H2CrO4', 'Thu đuợc axit H2CrO4 và H2', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Trong chiến tranh Việt Nam, Mĩ đã rải xuống các cánh rừng Việt Nam một loại hóa chất cực độc phá hủy môi trường và gây ảnh hưởng nghiệm trong đến sức khỏe của con người, đó là chất độc màu da cam. Chất độc này còn được gọi là', 'Đioxin', '3-MCPD', 'TNT', 'Nicôtin', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chất X vừa tác dụng được với axit, vừa tác dụng được với bazơ. Chất X là', 'CH3COOH.', 'CH3CHO.', 'H2NCH2COOH.', 'CH3NH2.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Có các dung dịch sau phenylamoniclorua ; anilin, axit aminoaxetic ; ancol benzylic ; metyl axetat. Số chất phản ứng được với dung dịch KOH là', '4.', '5.', '2.', '3.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chất nào sau đây không thủy phân trong môi trường axit?
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Dung dịch các chất sau có cùng nồng độ mol/lít glyxin (1), lysin (2) và axit oxalic (3). Giá trị pH của các dung dịch trên tăng dần theo thứ tự là', '(3), (1), (2).', '(1), (2), (3).', '(2), (3), (1).', '(3), (2), (1).', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Thủy phân este X (C4H6O2) trong môi trường axit, thu được anđehit. Công thức của X là', 'CH2=CHCOOCH3.', 'CH3COOCH=CH2.', 'CH3COOCH3.', 'HCOOCH2CH=CH2.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Phát biểu nào sau đây không đúng?', 'Metylamin làm xanh quỳ tím ẩm.', 'Glyxin (H2NCH2COOH) phản ứng được với dung dịch NaOH.', 'Tripeptit hòa tan Cu(OH)2 tạo dung dịch màu xanh.', 'Peptit bị thủy phân trong môi trường axit và kiềm.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Chọn phát biểu không đúng:', 'Axit panmitic, axit stearic là các axit béo chủ yếu thường gặp trong thành phần của chất béo trong hạt, quả.', 'Khi đun nóng glixerol với các axit béo,có H2SO4, đặc làm xúc tác, thu được chất béo.', 'Ở động vật, chất béo tập trung nhiều trong mô mỡ. Ở thực vật, chất béo tập trung nhiều trong hạt, quả...', 'Chất béo là trieste của glixerol với các axit béo.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Cho các chất sau: Axit glutamic, Alanin, Amoni axetat, Nhôm, Nhôm sunfat, phèn chua, Natri hidrocacbonat và nhôm oxit. Số chất lưỡng tính là', '7', '8', '6', '5', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Nhận xét nào sau đây không đúng?', 'Poli (metyl metacrylat) được dùng làm thủy tinh hữu cơ.', 'Metyl axetat là đồng phân của axit axetic.', 'Metyl fomat có nhiệt độ sôi thấp hơn axit axetic.', 'Các este thường nhẹ hơn nước và ít tan trong nước.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Cho các phát biểu sau:
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Axit nào sau đây là axit béo?
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Phát biểu nào sai?', 'Tính axit của phenol yếu hơn tính axit của axit cacbonic.', 'Anilin có tính bazơ nên dung dịch làm quỳ tím hoá xanh.', 'Tính bazơ của amoniac yếu hơn của metylamin nhưng mạnh hơn phenylamin.', 'Trong phân tử anilin, vòng benzen và nhóm NH2 có ảnh hưởng qua lại lẫn nhau.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Thuỷ phân hợp chất: H2N-CH(CH3)-CO-NH-CH2-CO-NH-CH2-CH2-CO-NH-CH(C6H5)COOH thì thu được nhiều nhất bao nhiêu -amino axit?', '3.', '5.', '4.', '2.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Cho các dung dịch loãng sau (có cùng nồng độ mol):
(1) CH3COONa; (2) ClCH2COONa; (3) CH3CH2COONa và (4) NaCl.
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 1, 'Chương 1: Cân bằng hóa học', 1, 'Thuỷ phân không hoàn toàn một octapeptit sau Gly-Ala-Phe-Val-Gly-Gly-Ala-Gly được tối đa bao nhiêu đipeptit khác nhau và chứa 2 gốc α-amino axit khác nhau?', '6', '7', '4', '5', 'D');
