INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 2, 'Chương 5: Dẫn xuất halogen – Alcohol – Phenol', 1, 'Dữ kiện thực nghiệm nào không dùng để chứng minh cấu tạo của glucozơ?', 'Tạo kết tủa đỏ gạch khi đun nóng với Cu(OH)2.', 'Hoà tan Cu(OH)2 ở nhiêt độ thường tạo dung dịch màu xanh lam.', 'Lên men thành ancol (rượu) etylic.', 'Tạo este chứa 5 gốc axit trong phân tử.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 2, 'Chương 5: Dẫn xuất halogen – Alcohol – Phenol', 1, 'Cho các chất sau: phenol, etanol, axit axetic, natri phenolat, natri hiđroxit. Số cặp chất tác dụng được với nhau là', '2.', '4.', '3.', '1', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 2, 'Chương 6: Hợp chất carbonyl – Carboxylic acid', 1, 'Cacbohiđrat nhất thiết phải chứa nhóm chức của', 'Amin', 'Xeton', 'Ancol', 'Anđehit', 'C');
