INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 2, 'Chương 6: Hợp chất carbonyl – Carboxylic acid', 1, 'Cho dãy các chất: anđehit axetic, axetilen, glucozơ, axit axetic, metyl fomat. Số chất trong dãy có khả năng tham gia phản ứng tráng bạc là', '5', '2', '4', '3', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 2, 'Chương 6: Hợp chất carbonyl – Carboxylic acid', 1, 'Chất nào dưới đây vừa phản ứng được với dung dịch NaOH, vừa có khả năng tham gia phản ứng tráng bạc?', 'HCOOCH=CH2.', 'CH2=CHCOOH.', 'CH3COOCH3.', 'HOCH2CH2OH.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (11, 2, 'Chương 6: Hợp chất carbonyl – Carboxylic acid', 1, 'Dãy các chất nào sau đây có thể tham gia phản ứng tráng bạc (tráng gương):', 'Fructozơ, anđehit axetic, axit fomic, metyl glicozit.', 'Glixerol, axetilen, trpanmitin, sobitol.', 'Glucozơ, anđehit fomic, axit fomic, metyl fomat.', 'Glucozơ, fructozơ, anđehit fomic, vinyl axetilen.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Cho các phát biểu sau:
(a) Chất béo được gọi chung là triglixerit hay triaxylglixerol.
(b) Chất béo nhẹ hơn nước, không tan trong nước nhưng tan nhiều trong dung môi hữu cơ.
(c) Phản ứng thủy phân chất béo trong môi trường axit là phản ứng thuận nghịch.
(d) Tristearin, triolein có công thức lần lượt là (C 17H33COO)3C3H5, (C17H35COO)3C3H5.
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Phát biểu không đúng là', 'Aminoaxit là những chất rắn, kết tinh, tan tốt trong nước va có vị ngọt.', 'Hợp chất H2N-CH2-COOH3N-CH3 là este của glyxin (glixin).', 'Aminoaxit là hợp chất hữu cơ tạp chức, phân tử chứa đồng thời nhóm amino và nhóm
