INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Phản ứng thủy phân este trong môi trường kiềm,  nóng gọi là', 'phản ứng lên men.', 'phản ứng hidrat hoá.', 'phản ứng cracking', 'phản ứng xà phòng hoá.', 'D');
