INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Vinyl axetat là chất nào sau đây', 'HCOOCH=CH2', 'CH3COOCH=CH2', 'CH2=CHCOOCH3', 'C H3COOC2H5', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Phát biểu nào sau đây không đúng?', 'Benzyl axetat có mùi thơm của hoa nhài', 'Isoamyl axetat có mùi thơm của chuối chín', 'Các este rất ít tan trong nước', 'Một số este được dùng làm chất dẻo', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Cho các phát biểu sau:
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Nhận định nào sau đây không đúng?', 'Khi thay nhóm OH ở nhóm cacboxyl của axit cacboxylic bằng nhóm OR thì được este.', 'Lipit là những hợp chất hữa cơ có trong tế bào sống tan nhiều trong nước và không tan trong dung môi hữu cơ không phân cực.', 'Phản ứng thủy phân este trong môi trường kiềm là phản ứng một chiều và gọi là phản ứng xà phòng hóa.', 'Tên của este RCOOR gồm tên gốc R cộng thêm tên gốc axit RCOO (đuôi “at”).', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Xà phòng hóa hóa chất nào sau đây thu được glixerol?', 'Metyl axetat', 'Benzyl axetat', 'Tristearin', 'Metyl fomat', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Khối lượng mol (g/mol) của este có mùi chuối chín là', '144.', '130.', '102.', '116.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Hai chất nào sau đây đều thủy phân được trong dung dịch NaOH đun nóng?', 'Saccarozơ và tristearin.', 'Xenlulozơ và triolein.', 'Etyl axetat và Gly-Ala.', 'Etylamin và Metyl fomat.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Polivinyl axetat (hoặc poli(vinyl axetat)) là polime được điều chế bằng phản ứng trùng hợp', 'CH2=CH-COO-C2H5.', 'CH2=CH-COO-CH3.', 'C2H5COO-CH=CH2.', 'CH3COO-CH=CH2.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Chất thơm X thuộc loại este có công thức phân tử C8H8O2. Chất X không được điều chế từ ancol và axit tương ứng và có khả năng tham gia phản ứng tráng gương. Công thức cấu tạo thu gọn của X là', 'H-COO-CH2-C6H5', 'CH3COO-C6H5', 'H-COO-C6H4-CH3', 'C6H5-COO-CH3', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Trong phân tử este no, đơn chức có số liên kết pi là', '0', '1', '2', '3', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Khẳng định không đúng về chất béo là', 'Đun chất béo với dung dịch NaOH thì thu được sản phẩm có khả năng hòa tan Cu(OH)2.', 'Chất béo là trieste của glixerol với axit béo.', 'Chất béo và dầu mỡ bôi trơn máy có cùng thành phần nguyên tố.', 'Chất béo nhẹ hơn nước.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Dầu chuối là este có tên isoamyl axetat, được điều chế từ', 'CH3OH, CH3COOH.', '(CH3)2CHCH2OH, CH3COOH.', 'C2H5COOH, C2H5OH.', 'CH3COOH, (CH3)2CHCH2CH2OH.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Xà phòng hóa chất nào sau đây thu được glixerol?', 'Benzyl axetat.', 'Metyl fomat.', 'Triolein.', 'Metyl axetat.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Một este có công thức phân tử là C3H6O2, có tham gia phản ứng tráng bạc. CTCT của este đó là', 'HCOOC3H7', 'C2H5COOCH3', 'HCOOC2H5', 'CH3COOCH3', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Chất nào sau đây là este', 'H2N-CH(CH3)-COOH', 'CH3-NH2', 'CH3COOCH3', 'C6H5NH3Cl', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Etyl axetat có công thức hóa học là', 'CH3COOCH3.', 'HCOOC2H5.', 'CH3COOC2H5.', 'HCOOCH3.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Triolein là chất béo', 'rắn, no', 'rắn, không no', 'lỏng, không no', 'lỏng, no', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Một este có CTPT là C3H6O2 có khả năng tham gia phản ứng tráng bạc với dung dịch AgNO3/NH3. CTCT thu gọn của este đó là', 'C2H5COOCH3', 'HCOOC3H7', 'HCOOC2H5', 'CH3COOCH3', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Công thức tổng quát của este no, đơn chức là', 'CnH2nO2', 'CxHyOz', 'RCOOR’', 'CnH2 n-2O2', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Công thức nào sau đây không thể là công thức đơn giản của 1 este no, mạch hở', 'C5H8O2', 'C5H9O2', 'C4H5O4', 'C5H10O', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Hai chất hữu cơ X1 và X2 đều có khối lượng phân tử bằng 60 đvC. X1 có khả năng phản ứng với: Na, NaOH, Na2CO3. X2 phản ứng với NaOH (đun nóng) nhưng không phản ứng Na. Công thức cấu tạo của X1, X2   lần lượt là', '(CH3)2CH-OH, H-COO-CH3.', 'CH3-COOH, CH3-COO-CH3.', 'H-COO-CH3, CH3-COOH.', 'CH3-COOH, H-COO-CH3.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Cho các este: etyl fomat (1), vinyl axetat (2), triolein (3), metyl acrylat (4), phenyl axetat(5). Dãy gồm các este đều phản ứng được với dung dịch NaOH (đun nóng) sinh ra ancol là', '(1), (3), (4).', '(3), (4), (5).', '(1), (2), (3).', '(2), (3), (5).', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Để chuyển dầu thực vật (chất béo lỏng) thành bơ nhân tạo (chất béo rắn), người ta thực hiện quá trình', 'thủy phân chất béo', 'đề hidro hóa chất béo', 'xà phòng hóa chất béo', 'hidro hóa chất béo lỏng', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Chất X có CTPT là C4H8O2 khi tác dụng với dung dịch NaOH sinh ra chất Y có CTPT là C2H3O2Na và chất Z có công thức là C2H6O. X thuộc loại nào sau đây?', 'Este', 'Anđehit', 'Axit', 'Ancol', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Hãy chọn định nghĩa đúng trong các định nghĩa sau:', 'Este là những hợp chất hữu cơ trong phân tử có nhóm chức –COO- liên kết với các gốc R và R’', 'Este là hợp chất sinh ra khi thế nhóm –OH trong nhóm COOH của phân tử axit bằng nhóm OR.', 'Este là sản phẩm phản ứng khi cho rượu tác dụng với axit cacboxylic', 'Este là sản phẩm phản ứng khi cho rượu tác dụng với axit.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Trong công nghiệp, một lượng lớn chất béo dùng để sản xuất', 'xà phòng và glixerol.', 'glucozơ và ancol etylic.', 'glucozơ và glixerol.', 'xà phòng và ancol etylic.', 'A');
