INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Chỉ ra đâu không phải là polime?', 'Xemlulozơ', 'Amilozơ', 'thủy tinh hữu cơ', 'Lipit', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Tên gọi của este có CTCT thu gọn: CH3COOCH(CH3)2 là', 'Propyl axetat', 'iso-propyl axetat', 'Sec-propyl axetat', 'Propyl fomat', 'B');
