INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Phát biểu không đúng là', 'Trong dung dịch, H2N-CH2-COOH còn tồn tại ở dạng ion lưỡng cực H3N+-CH2-COO-.', 'Aminoaxit là hợp chất hữu cơ tạp chức, phân tử chứa đồng thời nhóm amino và nhóm cacboxyl.', 'Aminoaxit là những chất rắn, kết tinh, tan tốt trong nước và có vị ngọt.', 'Hợp chất H2N-CH2-COOH3N-CH3 là este của glyxin (hay glixin).', 'D');
