INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Hãy cho biết trong các phát biểu sau, phát biểu nào đúng?', 'Trong phản ứng este hoá, H2SO4 đặc đóng vai trò chất xúc tác và  hút nước để chuyển dịch cân bằng.', 'Phản ứng xà phòng hoá các chất béo là phản ứng thuận nghịch.', 'Lipit là các hợp chất được tổng hợp từ các axit béo và glixerol.', 'Trong phản ứng thuỷ phân este, H2SO4 đóng vai trò chất xúc tác và hút nước để chuyển dịch cân bằng', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 1: Ester – Lipid', 1, 'Hợp chất X có công thức cấu tạo CH3CH2 - COO - C2H5. Tên gọi của X là', 'vinyl axetat', 'etyl propionat', 'metyl metacrylat', 'metyl propionat Câu 997: Điện phân dung dịch chứa (x mol KCl và y mol Cu(NO3)2) thu được dung dịch có khả năng hòa tan được MgO. Liên hệ giữa x, y là
