INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Một phân tử saccarozơ có:', 'một gốc  -glucozơ và một gốc  -fructozơ.', 'một gốc  -glucozơ và một gốc  -fructozơ.', 'hai gốc  -glucozơ.', 'một gốc  -glucozơ và một gốc -fructozơ.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Phát biểu không đúng là', 'Dung dịch fructozơ hoà tan được Cu(OH)2.', 'Dung dịch mantozơ tác dụng với Cu(OH)2 khi đun nóng cho kết tủa Cu2O.', 'Sản phẩm thủy phân xenlulozơ (xúc tác H+, to) có thể tham gia phản ứng tráng gương.', 'Thủy phân (xúc tác H+, to) saccarozơ cũng như mantozơ đều cho cùng một monosaccarit.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Phát biểu nào sau đây là đúng?', 'Amilopectin có cấu trúc mạch phân nhánh', 'Glucozơ bị khử bởi dung dịch AgNO3 trong NH3', 'Saccarozơ làm mất màu nước brom', 'Xenlulozơ có cấu trúc mạch phân nhánh', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Cho các phát biểu sau về cacbohiđrat:
(a) Tất cả các cacbohiđrat đều có phản ứng thủy phân.
(b) Thủy phân hoàn toàn tinh bột thu được glucozơ.
(c) Glucozơ, fructozơ và mantozơ đều có phản ứng tráng bạc.
(d) Glucozơ làm mất màu nước brom.
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Cho các phát biểu sau:
(a) Glucozơ có khả năng tham gia phản ứng tráng bạc
(b) Glucozơ và fructozơ đều có phản ứng làm mất màu dung dịch brom.
(c) Fructozơ có khả năng tham gia phản ứng tráng bạc
(d) Saccarozơ được cấu tạo từ hai gốc -glucozơ và -fructozơ
