INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Để chứng minh trong phân tử của glucozơ có nhiều nhóm hiđroxyl, người ta cho dung dịch
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Cho các phát biểu sau về cacbohiđrat:
(a) Glucozơ và saccarozơ đều là chất rắn có vị ngọt, dễ tan trong nước.
(b) Tinh bột và xenlulozơ đều là polisaccarit
(c) Trong dung dịch, glucozơ và saccarozơ đều hòa tan Cu(OH)2, tạo phức màu xanh lam.
(d) Khi thủy phân hoàn toàn hỗn hợp gồm tinh bột và saccarozơ trong môi trường axit, chỉ thu được một loại monosaccarit duy nhất.
(e) Khi đun nóng glucozơ (hoặc fructozơ) với dung dịch AgNO3 trong NH3 thu được Ag.
(g) Glucozơ và saccarozơ đều tác dụng với H2 (xúc tác Ni, đun nóng) tạo sobitol.
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Thí nghiệm nào sau đây chứng tỏ trong phân tử glucozơ có 5 nhóm hiđroxyl?', 'Khử hoàn toàn glucozơ thành hexan', 'Cho glucozơ tác dụng với Cu(OH)2', 'Tiến hành phản ứng tạo este của glucozơ với anhiđrit axetic', 'Thực hiện phản ứng tráng bạc', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Cho các phát biểu sau:
(a) Có thể dùng nước brom để phân biệt glucozơ và fructozơ
(b) Trong môi trường axit, glucozơ và fructozơ có thể chuyển hóa lẫn nhau
(c) Có thể phân biệt glucozơ và fructozơ bằng phản ứng với dung dịch AgNO 3 trong NH3
(d) Trong dung dịch, glucozơ và fructozơ đều hòa tan Cu(OH) 2 ở nhiệt độ thường cho dung dịch màu xanh lam
(e)Trong dung dịch, fructozơ tồn tại chủ yếu ở dạng mạch hở
(f) Trong dung dịch, glucozơ tồn tại chủ yếu ở dạng mạch vòng 6 cạnh (dạng α và β)
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Dãy gồm các dung dịch đều tham gia phản ứng tráng bạc là', 'Frutozơ, mantozơ, glixerol, anđehit axetic', 'Glucozơ, mantozơ, axit fomic, anđehit axetic', 'Glucozơ, frutozơ, mantozơ, saccarozơ', 'Glucozơ, glixerol, mantozơ, axit fomic.', 'B');
