INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Khi bị ốm, mất sức, nhiều người bệnh thường được truyền dịch đường để bổ sung nhanh năng lượng. Chất trong dịch truyền có tác dụng trên là', 'Glucozơ.', 'Saccarozơ.', 'Fructozơ.', 'Mantozơ', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Trong công nghiệp tráng gương như: Tráng phích, tráng gương soi, gương trang trí ngư ời ta làm như sau: Đ ầu tiên là làm sạch bề mặt thuỷ tinh, sau đó người ta cho muối thiếc tráng qua bề mặt thuỷ tinh, rồi cho hổn hợp AgNO3/NH3  dư vào bề mặt kính, sau đó cho tiếp một hoá chất X vào rồi bắt đâu gia nhiệt.Hỏi X l à chất nào sau đây?', 'Andehyt fomic', 'Glucozơ', 'Andehyt axetic', 'Axetilen', 'B');
