INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Năm dung dịch A1, A2, A3, A4, A5 cho tác dụng với Cu(OH)2/NaOH trong điều kiện thích hợp thì thấy: A1 tạo màu tớm, A2 tạo màu xanh lam, A3 tạo kết tủa khi đun nóng, A4 tạo dung dịch màu xanh lam và khi đun nóng thì tạo kết tủa đỏ gạch, A5 không có hiện tượng gỡ. A1, A2, A3, A4, A5 lần lượt là', 'Protein, saccarozơ, lipit, fructozơ, anđehit fomic.', 'Lipit, saccarozơ, anđehit fomic, fructozơ, protein.', 'Protein, lipit, saccarozơ, glucơzơ, anđehit fomic.', 'Protein, saccarozơ, anđehit fomic, fructozơ, lipit.', 'D');
