INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Cho các phát biểu sau:
(1)Glucozơ, fructozơ đều có khả năng tham gia phản ứng tráng bạc;
(2)Saccarozơ, tinh bột và xemlulozơ đều bị thủy phân khi có axit H2SO4 (loãng) làm xúc tác;
(3)Tinh bột và xenlulozơ đều được tạo thành trong cây xanh nhờ quá trình quang hợp;
(4)Glucozơ, fructozơ đều có khả năng hòa tan Cu(OH)2 thành dung dịch màu xanh.       
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 2: Carbohydrate', 1, 'Fructozơ và saccarozơ đều có', '5 nhóm hiđroxyl trong phân tử.', 'phản ứng hòa tan Cu(OH)2 ở nhiệt độ thường.', 'phản ứng tráng bạc.', 'phản ứng khử brom trong dung dịch nước.', 'B');
