INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Phát biểu nào sau đây là đúng?', 'Tất cả các peptit đều có phản ứng màu biure.', 'Muối phenylamoni clorua không tan trong nước.', 'H2N-CH2-CH2-CO-NH-CH2-COOH là một đipeptit.', 'Ở điều kiện thường, metylamin và đimetylamin là những chất khí có mùi khai.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Phát biểu nào sau đây là sai?', 'Anilin tác dụng với nước Brom tạo thành kết tủa trắng.', 'Dung dịch lysin làm xanh quỳ tím.', 'Cho Cu(OH)2 vào dung dịch lòng trắng trứng thấy xuất hiện màu vàng.', 'Dung dịch glyxin không làm đổi màu quỳ tím.', 'C');
