INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Khi nói về protein, phát biểu nào sau đây sai?', 'Protein có phản ứng màu biure.', 'Tất cả các protein đều tan trong nước tạo thành dung dịch keo.', 'Protein là những polipeptit cao phân tử có phân tử khối từ vài chục nghìn đến vài triệu.', 'Thành phần phân tử của protein luôn có nguyên tố nitơ', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Amino axit X có phân tử khối bằng 75. Tên của X là', 'alanin.', 'valin.', 'lysin.', 'glyxin.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Dung dịch nào sau đây làm quỳ tím đổi thành màu xanh?', 'Dung dịch valin.', 'Dung dịch alanin.', 'Dung dịch glyxin.', 'Dung dịch lysin.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Chất nào sau đây là amin bậc 2?', 'H2N-CH2-NH2.', '(CH3)2CH-NH2.', 'CH3-NH-CH3.', '(CH3)3N', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Dãy gồm các chất đều làm giấy quỳ tím ẩm chuyển sang màu xanh là', 'amoni clorua, metyl amin, natri hiđroxit.', 'anilin, amoniac, natri hiđroxit..', 'metyl amin, amoniac, natri axetat.', 'anilin, metyl amin, amoniac.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Có bao nhiêu tripeptit (mạch hở) khác loại mà khi thủy phân hoàn toàn đều thu được 3 aminoaxit: glyxin, alanin và phenylalanin?', '3.', '4.', '6.', '9.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Alanin có công thức là', 'H2N-CH2-CH2-COOH', 'CH3-CH(NH2)-COOH', 'C6H5-NH2', 'H2N-CH2-COOH', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Khi nói về peptit và protein, phát biểu nào sau đây là sai?', 'Protein có phản ứng màu biure với Cu(OH)2.', 'Tất cả các protein đều tan trong nước tạo thành dung dịch keo', 'Liên kết của nhóm CO với nhóm NH giữa hai đơn vị α-amino axit được gọi là liên kết peptit.', 'Thủy phân hoàn toàn protein đơn giản thu được các  α –amino axit.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Phát biểu nào sau đây là đúng?', 'Các ancol đa chức đều phản ứng với Cu(OH)2 tạo dung dịch màu xanh lam.', 'Metyl amin, đimetyl amin, trimetyl amin, etyl amin đều là chất khí ở điều kiện thường.', 'Tất cả các amin đều tan tốt trong nước, dung dịch của nó có môi trường bazơ yếu nên làm quỳ chuyển xanh, phenolphalein chuyển hồng.', 'Trong phân tử của đipeptit có 2 liên kết peptit.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Dãy các chất tác dụng được với dung dịch NaOH ở điều kiện thích hợp là', 'glucozơ; metyl amin; xenlulozơ; axit axetic.', 'etyl axetat; anilin; ala – gly – ala; glucozơ.', 'etyl axetat; alanin; ala – gly – ala; axit axetic.', 'alanin; ala – aly – ala; anilin; triolein.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Dung dịch nào sau đây làm quỳ tím chuyển màu hồng?', 'lysin', 'alanin', 'glyxin', 'axit glutamic', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Số đồng phân tripeptit tạo thành từ 1 phân tử glyxin và 2 phân tử alanin là', '2.', '3.', '5.', '4.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Thủy phân hoàn toàn 1 mol peptit X sinh ra 2 mol Gly, 1 mol Met, 1 mol Phe và 1 mol Ala. Dùng phản ứng đặc trưng xác định được amino axit đầu là Met va amino axit đuôi là Phe. Thủy phân từng phần X thu được các peptit Met-Gly, Gly-Ala và Gly-Gly. Trình tự đúng của X là', 'Met-Gly-Ala-Gly-Phe', 'Met-Gly-Ala-Met-Phe', 'Met-Ala-Gly-Gly-Phe', 'Met-Gly-Gly-Ala-Phe', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Anilin có công thức hóa học là', 'C6H5OH.', 'C6H5NH2.', 'CH3OH.', 'CH3COOH.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 3: Hợp chất chứa nitrogen', 1, 'Protein có phản ứng màu biure với:', 'Ca(OH)2', 'KOH', 'NaOH', 'Cu(OH)2', 'D');
