(5). Các chất có khả năng tham gia phản ứng trùng hợp tạo polime là', '(3), (4) và (5', '(1), (2) và (3)', '(1), (3) và (5)', '(1), (2) và (5)', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Các polime thuộc loại tơ nhân tạo là', 'tơ visco và tơ xenlulozơ axetat', 'tơ tằm và tơ vinilon.', 'tơ nilon-6,6 và tơ capron', 'tơ visco và tơ nilon-6,6', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Cho các loại tơ: bông, tơ capron, tơ xenlulozơ axetat, tơ tằm, tơ nitron, nilon-6,6. Số tơ tổng hợp là', '2.', '3.', '5.', '4.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Sản phẩm hữu cơ của phản ứng nào sau đây không dùng để chế tạo tơ tổng hợp?', 'A. Trùng ngưng axit ε-aminocaproic.', 'Trùng hợp metyl metacrylat.', 'Trùng hợp vinyl xianua.', 'Trùng ngưng hexametylenđiamin với axit ađipic.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Cho các tơ sau: tơ xenlulozơ axetat, tơ capron, tơ nitron, tơ visco, tơ nilon-6,6. Có bao nhiêu tơ thuộc loại tơ poliamit?', '3', '1', '2', '4', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Trong các polime sau: (1) poli(metyl metacrylat); (2) polistiren; (3) nilon-7; (4) poli(etylen- terephtalat); (5) nilon-6,6; (6) poli(vinyl axetat), các polime là sản phẩm của phản ứng trùng ngưng là
(1), (3), (6).
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Metyl metacrylat là một este được ứng dụng rộng rãi trong các ngành công nghiệp. Đó là ngành công nghiệp nào?', 'sản xuất thuốc nổ.', 'sản xuất thủy tinh hữu cơ.', 'sản xuất bánh kẹo.', 'sản xuất xà phòng và chất tảy rửa tổng hợp.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Nhận xét nào sau đây không chính xác', 'Chất dẻo là những vật liệu polime có tính dẻo và tính đàn hồi.', 'Tơ là những vật liệu polime hình sợi dài và mảnh với độ bền nhất định.', 'PVC là chất rắn vô định hình, cách điện tốt, bền với axit, được dùng làm vật liệu cách điện, ống dẫn nước, vải che mưa,…', 'Cao su là vật liệu polime có tính đàn hồi.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Polime có các mắt xích nối với nhau thành mạch không phân nhánh là', 'cao su lưu hóa', 'glicogen', 'amilozo', 'aminopectin', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Cho các polime sau: tơ nitron (hay olon), tơ nilon-6, PE, PVC. Số polime được điều chế bằng phản ứng  trùng hợp là', '1', '2', '3', '4', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Tơ xenlulozo thuộc loại:', 'tơ tổng hợp', 'polime tổng hợp', 'tơ tự nhiên', 'tơ nhân tạo', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Chất tham gia phản ứng trùng ngưng là', 'C2H5OH.', 'H2NCH2COOH.', 'CH3COOH.', 'CH2=CHCOOH', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Chất nào sau đây không có khả năng tham gia phản ứng trùng ngưng:', 'HOCH2CH2OH.', 'HCOOCH2CH2CH2NH2.', 'CH3CH(NH2)COOH.', 'CH3CH(OH)COOH.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Tơ nitron dai, bền với nhiệt, giữ nhiệt tốt, thường được dùng để dệt vải và may quần áo ấm. Trùng hợp chất nào sau đây tạo thành polime dùng để sản xuất tơ nitron?', 'CH2=CH-CN', 'C6H5-CH=CH2', 'H2N-[CH2]5-COOH', 'CH2=CH-Cl', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Chất được dùng nhiều làm màng mỏng, vật liệu cách điện, bình chứa là', 'polietilen (PE)', 'Poli(vinyl clorua) (PVC)', 'nilon – 6,6', 'Cao su thiên nhiên', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Phát biểu nào sau đây sai?', 'Chất dẻo là những vật liệu có tính dẻo.( vật liêu polime )', 'Tơ visco, xenlulozơ axetat là tơ bán tổng hợp.', 'Cao su thiên nhiên là polime của isopen.', 'Đa số polime không tan trong các dung môi thông thường.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Nhóm các vật liệu nào dưới đây được chế tạo từ polime trùng ngưng', 'Nilon-6,6, tơ lapsan, tơ enang', 'Nilon-6,6, tơ lapsan, tơ visco', 'Cao su Buna,nilon-6,6, tơ nitron', 'Tơ axetat, nilon-6,6, nilon-7.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Phát biểu nào sau đây sai?', 'Glyxin, alanin là các α – aminoaxit.', 'Geranyl axetat có mùi hoa hồng.', 'Tơ nilon - 6,6 và tơ nitron đều là protein.', 'Glucozo là hợp chất tạp chức.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Quá trình kết hợp nhiều phân tử nhỏ (monome) thành phân tử lớn (polime) đồng thời giải phóng những phân tử nhỏ khác (thí dụ H2O) được gọi là phản ứng', 'xà phòng hóa', 'trùng hợp', 'thủy phân', 'trùng ngưng', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Tơ visco là thuộc loại', 'Tơ thiên nhiên có nguồn gốc thực vật', 'Tơ tổng hợp', 'Tơ thiên nhiên có nguồn gốc động vật', 'Tơ nhân tạo', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Tơ tổng hợp không thể điều chế bằng phản ứng trùng ngưng là', 'Tơ lapsan.', 'Tơ nilon-6.', 'Tơ nilon - 6,6.', 'Tơ nitron.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Phát biểu nào sau đây sai?', 'Tơ nilon – 6,6 và tơ nitron đều là protein..', 'Geranyl axetat có mùi hoa hồng.', 'Glucozơ là hợp chất tạp chức.', 'Glyxin, alanin là các α–amino axit.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Hợp chất có CTCT: -NH(CH ) -CO- n2 5 có tên là', 'tơ lapsan', 'tơ capron', 'tơ enang', 'tơ nilon', 'B');
