INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Những polime thiên nhiên hoặc tổng hợp có thể kéo thành sợi Dài và mảnh gọi là', 'Sợi', 'Cao su', 'Tơ', 'Chất dẻo', 'C');
