INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Cho các polime sau: Tơ tằm, tơ visco, tơ axetat, tơ nitron, cao su buna-S, poli(vinyl clorua), poli vinylaxetat, nhựa novolac. Số polime có chứa nguyên tố oxi trong phân tử là', '5.', '4.', '3.', '6.', 'A');
