INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Polime X là chất rắn trong suốt, có khả năng cho ánh sáng truyền qua tốt nên được dùng chế tạo thủy tinh hữu cơ plexiglas. Tên  gọi  của  X  là', 'poliacrilonitrin.', 'poli(metyl metacrylat).', 'poli(vinyl clorua).', 'polietilen.', 'B');
