INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Cho các polime sau: sợi bông (1), tơ tằm (2), sợi đay (3), tơ enang (4), tơ visco (5), tơ axetat (6), nilon-6,6 (7). Loại tơ có nguồn gốc xenlulozơ là?', '1, 2, 3, 5, 6', '1, 3, 5, 6', '5, 6, 7', '1, 2, 5, 7', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Tơ nào sau đây là tơ nhân tạo?', 'Tơ tằm.', 'Tơ nitron.', 'Tơ nilon–6,6.', 'Tơ visco.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Polime được tạo ra từ phản ứng trùng ngưng là', 'cao su Buna', 'PVC', 'tơ nilon-6,6', 'PE', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 1, 'Chương 4: Polymer', 1, 'Loại tơ nào sau đây thường dùng để dệt vải may quần áo ấm hoặc bện thành sợi “len” dệt áo rét?', 'Tơ nilon 6 – 6', 'Tơ lapsan', 'Tơ nitron', 'Tơ capron', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 5: Pin điện và điện phân', 1, 'Phương pháp thích hợp điều chế kim loại Ca từ CaCl2 là', 'điện phân CaCl2 nóng chảy', 'dùng Na khử Ca2+ trong dung dịch CaCl2', 'điện phân dung dịch CaCl2', 'nhiệt phân CaCl2', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 5: Pin điện và điện phân', 1, 'Để điều chế Na người ta dùng phương pháp nào sau đây?', 'Điện phân dung dịch NaCl', 'Cho K phản ứng với dung dịch NaCl.', 'Nhiệt phân NaNO2', 'Điện phân NaCl nóng chảy', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 5: Pin điện và điện phân', 1, 'Điện phân(điện cực trơ,có vách ngăn)một dung dịch chứa các iôn Fe3+, Fe2+, Cu2+ thứ tự các ion bị khử xảy ra ở catot là', 'Fe2+, Fe3+, Cu2+', 'Fe2+, Cu2+, Fe3+', 'Fe3+, Fe2+, Cu2+.', 'Fe3+, Cu2+, Fe2+', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 5: Pin điện và điện phân', 1, 'Để điều chế các kim loại kiềm, kiềm thổ ta dùng phương pháp nào sau đây?', 'Điện phân nóng chảy.', 'Thủy luyện.', 'Điện phân dung dịch.', 'Nhiệt luyện.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 5: Pin điện và điện phân', 1, 'Điện phân dung dịch ZnSO4 ở catot xảy ra quá trình:', 'Zn2+ + 2e  Zn', 'SO42- - 2e  S + 2O2', 'H2O + 2e  2OH- + ½ H2', 'H2O -2e   ½ O2  + 2 H+', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 5: Pin điện và điện phân', 1, 'Trong quá trình điện phân, những ion âm (anion) di chuyển về', 'anot, ở đây chúng bị khử', 'anot, ở đây chúng bị oxi hoá', 'catot, ở đây chúng bị khử', 'catot, ở đây chúng bị oxi hoá', 'B');
