INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Khẳng định nào sau đây không đúng:', 'Fe, Cr, Cu đều có thể điều chế bằng phương pháp nhiệt luyện', 'Ag là kim loại dẫn điện tốt nhất', 'Trong các phản ứng hóa học, kim loại luôn có tính khử', 'Cr là kim loại có nhiệt độ nóng chảy cao nhất', 'C');
