INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Cho thứ tự trong dãy điện hóa của một cặp oxi hóa-khử như sau Al3+/Al; Zn2+/Zn; Fe2+/Fe; Pb2+/Pb; Ag+/Ag. Phát biểu nào sau đây là đúng?', 'Nguyên tử Pb có thể khử Zn2+ trong dung dịch.', 'Nguyên tử Ag có thể khử Zn2+ trong dung dịch.', 'Nguyên tử Fe có thể khử Zn2+ trong dung dịch.', 'Nguyên tử Al có thể khử Zn2+ trong dung dịch.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Cho dãy các chất sau anđehit fomic, anđehit axetic, axit axetic, ancol etylic, glucozo, saccarozo, vinyl fomat. Số chất trong dãy khi đốt cháy hoàn toàn có số mol CO2 sinh ra bằng số mol O2  tham gia phản ứng là', '3', '4', '6', '5', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Chọn phát biểu sai trong các phát biểu sau:', 'Những kim loại có độ hoạt động trung bình như Mg, Fe, Sn,…thường được điều chế bằng phương pháp nhiệt luyện.', 'Nguyên tắc để điều chế kim loại là khử ion kim loại trong hợp chất thành nguyên tử.', 'Trong tự nhiên chỉ có một số ít kim loại như vàng, platin,… tồn tại ở trạng thái tự do.', 'Có thể điều chế các kim loại hoạt động trung bình hoặc yếu bằng cách điện phân dd muối của chúng.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Cho dãy các ion kim loại: K+; Ag+; Fe2+; Cu2+. Ion kim loại có tính oxi hóa mạnh nhất trong dãy là', 'Ag+', 'Cu2+', 'Fe2+', 'K+', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Để thu được kim loại Cu từ dung dịch CuSO4 theo phương pháp thủy luyện, có thể dùng kim loại nào sau đây?', 'Ca', 'Fe', 'Na', 'Ag', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Phát biểu nào sau đây sai?', 'Hợp kim liti - nhôm siêu nhẹ, được dùng trong kĩ thuật hàng không.', 'Sắt có trong hemoglobin của máu.', 'Phèn chua được dùng để làm trong nước đục.', 'Trong tự nhiên, các kim loại kiềm chỉ tồn tại ở dạng đơn chất.', 'D');
