INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Sự phá hủy kim loại hay hợp kim do kim loại tác dụng trực tiếp với các chất oxi hóa trong môi trường gọi là', 'Sự ăn mòn hóa học', 'Sự tác dụng của kim loại với nước', 'Sự khử kim loại', 'Sự ăn mòn điện hóa học', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Trong các phản ứng sau, phản ứng nào sai?', 'Al2O3 + 2NaOH  → NaAlO2+ H2O', 'Al2O3 +3CO → 2Al +3CO2', 'NaAlO2 +CO2 + H2O→ Al(OH)3 + NaHCO3', 'Al + NaOH + H2O → NaAlO2 + 3/2H2', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 6: Đại cương về kim loại', 1, 'Có năm dung dịch đựng riêng biệt trong năm ống nghiệm: (NH4)2SO4, FeCl2, Cr(NO3)3, K2CO3, Al(NO3)3. Cho dung dịch Ba(OH)2 đến dư vào năm dung dịch trên. Sau khi phản ứng kết thúc, số ống nghiệm có kết tủa là', '3', '5.', '4.', '2.', 'B');
