INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Hòa tan m gam hỗn hợp gồm Al, Fe vào dung dịch H2SO4 loãng (dư). Sau khi các phản ứng xảy ra hoàn toàn, thu được dung dịch X. Cho dung dịch Ba(OH)2 (dư) vào dung dịch X, thu được kết tủa Y. Nung Y trong không khí đến khối lượng không đổi, thu được chất rắn Z là', 'hỗn hợp gồm BaSO4 và Fe2O3.', 'hỗn hợp gồm BaSO4 và FeO.', 'hỗn hợp gồm Al2O3 và Fe2O3.', 'Fe2O3', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cấu hình electron không đúng ( 2 câu ko đúng nên sửa câu A)', 'Cr3+:  [Ar] 3d3', 'Cr ( z = 24):  [Ar] 3d44s2', 'Cr2+:  [Ar] 3d4', 'Cr ( z = 24):  [Ar] 3d54s1', 'B');
