INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Các kim loại nào sau đây luôn được bảo vệ trong môi trường không khí, nước nhờ lớp màng oxit?', 'Cr-Al', 'Fe-Cr', 'Al-Ca', 'Fe-M', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Chất rắn X màu đỏ thẫm tan trong nước thành dung dịch màu vàng. Một số chất như S, P, C, C2H5OH… bốc cháy khi tiếp xúc với X. Chất X là', 'Cu.', 'P.', 'CrO3.', 'Fe2O3.', 'C');
