INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cho các hợp chất của sắt có công thức là Fe2O3; Fe3O4; FeS2; FeCO3. Theo thứ tự trên thì đó là thành phần chính của loại quặng nào sau đây', 'Pirit; manhetit; xiđerit; hematit.', 'Manhetit; hematit; pirit; xiđerit.', 'Xiđerit; hematit; pirit; manhetit', 'Hematit; manhetit; pirit, xiđerit.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Khi cho các chất: Ag, Cu, CuO, Al, Fe vào dung dịch axit HCl thì các chất đều bị tan hết là', 'Cu, Al, Fe', 'Cu, Ag, Fe', 'CuO, Al, Fe', 'Al, Fe, Ag', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Có 3 ống nghiệm đựng3 dung dịch: Cu(NO3)2; Pb(NO3)2; Zn(NO3)2 được đánh số theo thứ tự ống là 1, 2, 3. Nhúng 3 lá kẽm( giống hệt nhau) X, Y, Z vào 3 ống thì khối lượng mỗi lá kẽm sẽ:', 'X tăng, Y tăng, Z không đổi.', 'X giảm, Y tăng, Z không đổi.', 'X tăng, Y giảm, Z không đổi.', 'X giảm, Y giảm, Z không đổi.', 'B');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Những kim loại nào sau đây có thể được điều chế theo phương pháp nhiệt luyện (bằng chất khử CO) từ oxit kim loại tương ứng là', 'Al, Cu', 'Ca, Cu', 'Fe, Ni', 'Mg, Fe', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cho hợp kim Fe – Cu; Fe- Zn; Fe – C; Fe – Ag; Fe – Al. Để các hợp kim trên ngoài không khí, số hợp kim mà sắt bị ăn mòn trước là', '4', '2', '3', '1', 'C');
