INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Trong thực tế không sử cách nào để bảo vệ kim loại sắt khỏi bị ăn mòn là', 'Gắn đồng với kim loại Fe.', 'Bôi dầu mở.', 'Phủ một lớp sơn lên bề mặt sắt.', 'Tráng kẽm lên bề mặt sắt.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cho các cặp oxi hoá - khử sau: Zn2+/Zn, Cu2+/Cu, Fe2+/Fe. Biết tính oxi hoá của các ion tăng dần theo thứ tự: Zn2+, Fe2+, Cu2+, tính khử giảm dần theo thứ tự: Zn, Fe, Cu. Trong các phản ứng hoá học sau, phản ứng không xảy ra là', 'Cu + FeCl2.', 'Zn + FeCl2', 'Fe + CuCl2.', 'Zn + CuCl2.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Thứ tự một số cặp oxi hóa - khử trong dãy điện hóa như sau: Fe2+/Fe; Cu2+/Cu; Fe3+/Fe2+. Cặp chất không phản ứng với nhau là', 'Fe và dung dịch CuCl2.', 'Fe và dung dịch FeCl3.', 'Fe và dung dịch FeCl2.', 'Cu và dung dịch FeCl3.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Hai dung dịch đều phản ứng được với kim loại Fe là', 'CuSO4 và HCl.', 'ZnCl2 và FeCl3.', 'HCl và AlCl3.', 'CuSO4 và ZnCl2.', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Phản ứng chứng tỏ hợp chất sắt II có tính oxi hóa là', 'Fe(OH)2 → FeO + H2O.', '2FeCl2 + Cl2 → 2FeCl3.', 'FeO + H2 → Fe + H2O.', 'FeCl2 + 2NaOH → Fe(OH)2 + 2NaCl.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Trường hợp nào sau đây không có sự phù hợp giữa tên quặng sắt và công thức hợp chất chính có trong quặng?', 'Xiđerit chứa FeCO3', 'Pirit chứa FeS2', 'Hematit nâu chứa Fe2O3', 'Manhetit chứa Fe3O4', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Phản ứng nào dưới đây không thể xảy ra
(1) Fe + MgSO4→Mg + FeSO4      (2) Fe + 2HCl → FeCl2+ H2
(3) Fe + 6HNO3 đ , nguội → Fe(NO3)3 + 3NO2 + 3H2O   (4) 2Fe + 3Cl2→2FeCl3', '(1),(3)', '(3),(4)', '(1),(2)', '(3)', 'A');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cho sắt dư vào dung dịch HNO3 loãng thì dung dịch thu được chứa', 'Fe(NO3)3.', 'Fe(NO3)2 hay Fe(NO3)3 tùy thuộc vào nồng độ HNO3.', 'Fe(NO3)2.', 'Fe(NO3)2 và Fe(NO3)3.', 'C');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cho luồng khí H2 (dư) qua hỗn hợp các oxit CuO, Fe2O3, ZnO, MgO nung ở nhiệt độ cao. Sau phản ứng hỗn hợp rắn còn lại là', 'Cu, FeO, ZnO, MgO', 'Cu, Fe, ZnO, MgO.', 'Cu, Fe, Zn, Mg.', 'Cu, Fe, Zn, MgO.', 'D');
INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Cho dãy các chất: Cr(OH)3, Al2(SO4)3, Mg(OH)2, Zn(OH)2, MgO, Cr2O3, Al, Al2O3. Số chất trong dãy có tính chất lưỡng tính là', '2', '5', '4', '3', 'C');
