INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Hòa tan hỗn hợp ba kim loại Zn, Fe, Cu bằng dung dịch HNO3 loãng. Sau khi phản ứng xảy ra hoàn toàn, thu được chất không tan là Cu. Phần dung dịch sau phản ứng có chứa chất tan nào?', 'Zn(NO3)2; Fe(NO3)3', 'Zn(NO3)2; Fe(NO3)3; Cu(NO3)2', 'Zn(NO3)2; Fe(NO3)2', 'Zn(NO3)2; Fe(NO3)2; Cu(NO3)2', 'D');
