INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Dãy nào sau đây gồm các kim loại đều có thể điều chế được bằng phương pháp nhiệt luyện:', 'Cr, Fe, Cu', 'Zn, Mg, Ag', 'Al, Cu, Ag', 'Ba, Fe, Cu', 'A');
