INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Một sợi dây phơi quần áo gồm một đoạn dây đồng nối với một đoạn dây thép. Hiện tượng nào sau đây xảy ra ở chỗ nối hai đoạn dây khi để lâu ngày?', 'Sắt và đồng đều bị ăn mòn.', 'Sắt và đồng đều không bị ăn mòn.', 'Sắt bị ăn mòn.', 'Đồng bị ăn mòn.', 'C');
