INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Trong các thí nghiệm sau: Nhúng thanh Fe vào dung dịch CuSO4 (1); Nhúng vật bằng gang vào cốc đựng dung dịch muối ăn (2); Nhúng thanh Cu vào dung dịch FeCl3 (3); Thanh Fe và thanh Cu (riêng biệt) cùng nhúng vào dung dịch HCl (4); Sợi dây sắt nối với sợi dây đồng trong không khí ẩm (5). Thí nghiệm xảy ra sự ăn mòn điện hoá học là', '( 1) , (2), (5)', '(1), (3), (4).', '(2), (3), (5).', '(1), (2).', 'D');
