INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Những kim loại nào sau đây có thể được điều chế theo phương pháp nhiệt luyện (bằng chất khử CO) từ oxit kim loại tương ứng là', 'Fe, Ni', 'Al, Cu', 'Ca, Cu', 'Mg, Fe', 'A');
