INSERT INTO CauHoi (lop, hoc_ki, chuong, muc_do, noidung, dapan_a, dapan_b, dapan_c, dapan_d, dapan_dung) VALUES (12, 2, 'Chương 8: Sơ lược về kim loại chuyển tiếp và phức chất', 1, 'Tại những bãi đào vàng, nước sông đã nhiễm một loại hóa chất cực độc do thợ vàng sử dùng để tách vàng khỏi cát và tạp chất. Đất ở ven sông cũng bị nhiễm chất độc này. Chất độc này cũng có nhiều trong vỏ sắn. Chất độc đó là', 'Đioxin', 'Xianua', 'Nicôtin', 'Thủy ngân', 'B');
